mapper.select:
SELECT ip.id as inspect_parameter_id, ip.name as inspect_parameter_name, ip.code as inspect_parameter_code, ii.id as inspect_item_id, ii.name as inspect_item_name, ii.code as inspect_item_code FROM lm_inspect_parameter ip INNER JOIN lm_task t ON ip.id = t.parameter_id INNER JOIN lm_inspect_item ii ON t.inspect_item_id = ii.id INNER join lm_inspection_order io on t.inspection_order_id=io.id WHERE t.is_deleted = 0 AND ip.is_deleted = 0 AND ii.is_deleted = 0 AND io.is_deleted = 0
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.status = #{query.status}
AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%')
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspect_item ii WHERE ii.id = t.inspect_item_id AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%') AND ii.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.create_time >= #{query.requestTimeStart} AND io.create_time <= #{query.requestTimeEnd} AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.material_id IN
#{materialId}
AND io.is_deleted = 0 )
GROUP BY ip.id, ip.name, ip.code, ii.id, ii.name, ii.code ORDER BY ii.code ASC, ip.code ASC

SELECT DISTINCT t.id , t.status, t.owner_id, t.return_reason AS returnReason, t.reject_reason AS rejectReason, t.terminate_reason AS terminateReason, t.parameter_config_id AS parameterConfigId, io.scheme_version_id AS schemeVersionId, (CASE WHEN EXISTS ( SELECT 1 FROM lm_inspection_scheme_judgment j WHERE j.parameter_config_id = t.parameter_config_id AND j.is_deleted = 0 ) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_judgment j WHERE j.parameter_config_id = t.parameter_config_id AND j.is_deleted = 0 ) THEN 1 ELSE 0 END) AS has_judgment_condition, io.id as inspection_order_id, io.order_no, io.batch_no, io.material_id, io.create_time as request_time, io.create_by as request_user_id, m.name as material_name, m.code as material_code, m.specification as material_spec
FROM lm_inspection_order io INNER JOIN lm_task t ON io.id = t.inspection_order_id left join lm_inspect_material m on io.material_id = m.id WHERE t.parameter_id = #{parameterId} AND t.inspect_item_id = #{inspectItemId} AND t.is_deleted = 0 AND io.is_deleted = 0
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.status = #{query.status}
AND EXISTS ( SELECT 1 FROM lm_inspect_parameter ip WHERE ip.id = t.parameter_id AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%') AND ip.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspect_item ii WHERE ii.id = t.inspect_item_id AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%') AND ii.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.create_time >= #{query.requestTimeStart} AND io.create_time <= #{query.requestTimeEnd} AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.material_id IN
#{materialId}
AND io.is_deleted = 0 )
ORDER BY CASE WHEN t.status = 'RETURN_PENDING_APPROVAL' THEN 0 ELSE 1 END ASC, t.inspect_item_code ASC, t.parameter_code ASC, io.create_time DESC

SELECT io.id as inspection_order_id, io.order_no as inspection_order_no, io.create_time as request_time, io.create_by as request_user_id FROM lm_inspection_order io INNER JOIN lm_task t ON io.id = t.inspection_order_id
io.is_deleted = 0 AND t.is_deleted = 0
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.status = #{query.status}
AND EXISTS ( SELECT 1 FROM lm_inspect_parameter ip WHERE ip.id = t.parameter_id AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%') AND ip.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspect_item ii WHERE ii.id = t.inspect_item_id AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%') AND ii.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.create_time >= #{query.requestTimeStart} AND io.create_time <= #{query.requestTimeEnd} AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.material_id IN
#{materialId}
AND io.is_deleted = 0 )
GROUP BY io.id, io.order_no, io.create_time, io.create_by ORDER BY io.create_time ASC

SELECT io.id as inspection_order_id, io.order_no, io.batch_no, io.create_time as request_time, io.create_by as request_user_id, m.name as material_name, m.code as material_code, m.specification as material_spec FROM lm_inspection_order io INNER JOIN lm_task t ON io.id = t.inspection_order_id LEFT JOIN lm_inspect_material m ON io.material_id = m.id WHERE io.is_deleted = 0 AND t.is_deleted = 0
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.status = #{query.status}
AND EXISTS ( SELECT 1 FROM lm_inspect_parameter ip WHERE ip.id = t.parameter_id AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%') AND ip.is_deleted = 0 )
AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%')
AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%')
AND EXISTS ( SELECT 1 FROM lm_inspect_item ii WHERE ii.id = t.inspect_item_id AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%') AND ii.is_deleted = 0 )
AND io.create_time >= #{query.requestTimeStart} AND io.create_time <= #{query.requestTimeEnd}
AND io.material_id IN
#{materialId}
GROUP BY io.id, io.order_no, io.batch_no, io.create_time, io.create_by, m.name, m.code, m.specification ORDER BY io.create_time DESC

SELECT t.*, COALESCE(sv.scheme_id, ssv.scheme_id) AS schemeId, (CASE WHEN EXISTS ( SELECT 1 FROM lm_inspection_scheme_judgment j WHERE j.parameter_config_id = t.parameter_config_id AND j.is_deleted = 0 ) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_judgment j WHERE j.parameter_config_id = t.parameter_config_id AND j.is_deleted = 0 ) THEN 1 ELSE 0 END) AS has_judgment_condition, ii.name as inspect_item_name, ii.code as inspect_item_code, ip.name as parameter_name, ip.code as parameter_code FROM lm_task t INNER JOIN lm_inspect_item ii ON t.inspect_item_id = ii.id INNER JOIN lm_inspect_parameter ip ON t.parameter_id = ip.id INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id AND sv.is_deleted = 0 LEFT JOIN lm_stability_scheme_version ssv ON io.scheme_version_id = ssv.id AND ssv.is_deleted = 0 WHERE t.inspection_order_id = #{inspectionOrderId} AND t.is_deleted = 0
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.status = #{query.status}
AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%')
AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%')
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.create_time >= #{query.requestTimeStart} AND io.create_time <= #{query.requestTimeEnd} AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.material_id IN
#{materialId}
AND io.is_deleted = 0 )
ORDER BY CASE WHEN t.status IN ('RETURN_PENDING_APPROVAL') THEN 0 ELSE 1 END ASC, ii.code ASC, ip.code ASC

SELECT t.status, COUNT(*) as count FROM lm_inspection_order io INNER JOIN lm_task t ON io.id = t.inspection_order_id left join lm_inspect_material m on io.material_id = m.id AND t.is_deleted = 0 AND io.is_deleted = 0
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.status = #{query.status}
AND EXISTS ( SELECT 1 FROM lm_inspect_parameter ip WHERE ip.id = t.parameter_id AND ip.name LIKE CONCAT('%', #{query.parameterName}, '%') AND ip.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.order_no LIKE CONCAT('%', #{query.inspectionOrderNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.batch_no LIKE CONCAT('%', #{query.batchNo}, '%') AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspect_item ii WHERE ii.id = t.inspect_item_id AND ii.name LIKE CONCAT('%', #{query.inspectItemName}, '%') AND ii.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.create_time >= #{query.requestTimeStart} AND io.create_time <= #{query.requestTimeEnd} AND io.is_deleted = 0 )
AND EXISTS ( SELECT 1 FROM lm_inspection_order io WHERE io.id = t.inspection_order_id AND io.material_id IN
#{materialId}
AND io.is_deleted = 0 )
GROUP BY t.status

SELECT t.owner_id as user_id, COUNT(*) as pending_task_count FROM lm_task t WHERE t.owner_id IN
#{userId}
AND t.status = 'PENDING_COMPLETION' AND t.is_deleted = 0 GROUP BY t.owner_id

SELECT DISTINCT t.inspect_item_id FROM lm_task t WHERE t.id IN
#{taskId}
AND t.is_deleted = 0

SELECT DISTINCT sit.team_id FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id IN
#{inspectItemId}
AND sit.is_deleted = 0

SELECT t.id as task_id, t.inspect_item_id, io.scheme_version_id, io.scheme_source AS schemeSource FROM lm_task t INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id WHERE t.id IN
#{taskId}
AND t.is_deleted = 0 AND io.is_deleted = 0

SELECT DISTINCT sit.team_id
FROM lm_inspection_scheme_item_teams sit
WHERE sit.inspect_item_id = #{inspectItemId}
AND sit.version_id = #{schemeVersionId}
AND sit.is_deleted = 0

SELECT DISTINCT ssit.team_id
FROM lm_stability_scheme_item_teams ssit
WHERE ssit.inspect_item_id = #{inspectItemId}
AND ssit.version_id = #{schemeVersionId}
AND ssit.is_deleted = 0

SELECT DISTINCT itu.user_id, it.id as team_id, it.name as team_name FROM lm_inspection_team_user itu INNER JOIN lm_inspection_team it ON itu.inspection_team_id = it.id WHERE itu.inspection_team_id IN
#{teamId}
AND it.is_deleted = 0 AND it.status = 1 ORDER BY itu.user_id

SELECT DISTINCT sit.team_id FROM lm_inspection_scheme_item_teams sit WHERE sit.version_id IN
#{vid}
AND sit.is_deleted = 0

SELECT COUNT(*) > 0
FROM lm_task t
WHERE t.sample_id = #{sampleId}
AND t.parameter_id = #{parameterId}
AND t.is_deleted = 0

SELECT COUNT(*) > 0
FROM lm_task t
WHERE t.inspection_order_id = #{inspectionOrderId}
  AND t.inspect_item_id = #{inspectItemId}
  AND t.parameter_id = #{parameterId}
  AND t.is_deleted = 0

SELECT COUNT(DISTINCT t.id) FROM lm_task t INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id WHERE t.id IN
#{taskId}
AND t.is_deleted = 0 AND io.is_deleted = 0 AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit INNER JOIN lm_inspection_team_user itu ON sit.team_id = itu.inspection_team_id WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND itu.user_id = #{userId} AND itu.is_deleted = 0 ) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit INNER JOIN lm_inspection_team_user itu ON ssit.team_id = itu.inspection_team_id WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND itu.user_id = #{userId} AND itu.is_deleted = 0 ) )

SELECT t.id, t.task_no, t.inspection_order_id, t.sample_id, t.sample_no, t.inspect_item_id, t.inspect_item_name, t.parameter_id, t.parameter_name, t.status, t.owner_id, t.owner_name, t.priority, t.expected_completion_time, t.actual_completion_time, t.remark, t.terminate_reason, t.terminate_time, t.create_time, COALESCE(sv.scheme_id, ssv.scheme_id) AS schemeId, (CASE WHEN EXISTS ( SELECT 1 FROM lm_inspection_scheme_judgment j WHERE j.parameter_config_id = t.parameter_config_id AND j.is_deleted = 0 ) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_judgment j WHERE j.parameter_config_id = t.parameter_config_id AND j.is_deleted = 0 ) THEN 1 ELSE 0 END) AS has_judgment_condition FROM lm_task t INNER JOIN lm_inspection_order io ON t.inspection_order_id = io.id LEFT JOIN lm_inspection_scheme_version sv ON io.scheme_version_id = sv.id AND sv.is_deleted = 0 LEFT JOIN lm_stability_scheme_version ssv ON io.scheme_version_id = ssv.id AND ssv.is_deleted = 0 WHERE t.inspection_order_id = #{inspectionOrderId} AND t.parameter_id = #{parameterId} AND t.is_deleted = 0
AND ( EXISTS ( SELECT 1 FROM lm_inspection_scheme_item_teams sit WHERE sit.inspect_item_id = t.inspect_item_id AND sit.version_id = io.scheme_version_id AND sit.is_deleted = 0 AND sit.team_id IN
#{teamId}
) OR EXISTS ( SELECT 1 FROM lm_stability_scheme_item_teams ssit WHERE ssit.inspect_item_id = t.inspect_item_id AND ssit.version_id = io.scheme_version_id AND ssit.is_deleted = 0 AND ssit.team_id IN
#{teamId}
) )
AND t.status = #{query.status}
ORDER BY t.create_time DESC
